use super::*;
use crate::update_work_tests::{build,debit,retire};
#[test]fn actual_ranked_read_returns_original_rows_with_probe_work_and_zero_physical_copy(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&law["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let maximum=s["maximumTurns"].as_u64().unwrap();let count=law["count"].as_u64().unwrap()as usize;let input=build(count,&mut bank,&mut fuel,maximum);let turn=semio_framework_value_clone_source_testing::admit_owned(input,(),RetainedCloneGrant{maximum_items:1,..bank});let work=turn.work;let(source,p)=turn.result.map_err(|_|()).unwrap();debit(&mut bank,&mut fuel,p,work);let mut read=PersistentListRead::new();let mut actual=Vec::new();for _ in 0..maximum{let input=source.borrow();let d=read.demand(input).unwrap();for g in [RetainedCloneGrant{maximum_items:0,..bank},RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..bank}]{let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||crate::effect::settle(g,|effect|read.advance(input,effect)));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));}let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||crate::effect::settle(RetainedCloneGrant{maximum_items:1,..bank},|effect|read.advance(input,effect)));assert_eq!(heap,(0,0));let work=turn.work;let step=turn.result.unwrap();let p=step.progress();assert_eq!(p.copied_bytes,d.copy_bytes+law["copyBytes"].as_u64().unwrap()as usize);debit(&mut bank,&mut fuel,p,work);match step{PersistentListReadStep::Row(_,at,row)=>{assert!(std::ptr::eq(row.get(),input.get().get(at).unwrap()));actual.push(*row.get());},PersistentListReadStep::Complete(_)=>break,_=>{}}}assert_eq!(serde_json::to_value(actual).unwrap(),serde_json::to_value((0..count as u64).collect::<Vec<_>>()).unwrap());let cached=crate::effect::settle(Default::default(),|effect|read.advance(source.borrow(),effect));assert_eq!(cached.work,0);assert!(matches!(cached.result.unwrap(),PersistentListReadStep::Complete(_)));read.begin_close();for _ in 0..maximum{if read.terminal_is_empty(){break}let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||crate::effect::settle(RetainedCloneGrant{maximum_items:1,..bank},|effect|read.close_step(effect)));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(&mut bank,&mut fuel,p,turn.work);}assert!(read.terminal_is_empty());drop(read);retire(source,&mut bank,&mut fuel,maximum);}
